edits.old:
inline void Status::Update(const Status& new_status) {
  if (!new_status.ok()) {
    *this = new_status;
  }
}

inline void Status::Update(Status&& new_status) {
  if (new_status.ok()) {
    *this = std::move(new_status);
  }
}

edits.new:
inline void Status::Update(const Status& new_status) {
  if (ok() && !new_status.ok()) {
    *this = new_status;
  }
}

inline void Status::Update(Status&& new_status) {
  if (ok() && !new_status.ok()) {
    *this = std::move(new_status);
  }
}
